    "Explore the iSuite website": "Explore the iSuite website",
    "06 / THE AUTO BARBER": "06 / THE AUTO BARBER",
    "Before software, there were real customers.": "Before software, there were real customers.",
    "I operated a Seattle-area automotive restyling and service business: six-figure revenue, 165+ Google reviews, and the everyday work of earning customer trust.": "I operated a Seattle-area automotive restyling and service business: six-figure revenue, 165+ Google reviews, and the everyday work of earning customer trust.",
    "Customers wanted automotive work they could trust, with clear communication and a dependable experience from the first inquiry to the finished job.": "Customers wanted automotive work they could trust, with clear communication and a dependable experience from the first inquiry to the finished job.",
    "Own the full customer journey: sales, marketing, service and follow-through.": "Own the full customer journey: sales, marketing, service and follow-through.",
    "Build operational habits around the work, not just the result.": "Build operational habits around the work, not just the result.",
    "Take responsibility for hiring, training and customer experience as the business grew.": "Take responsibility for hiring, training and customer experience as the business grew.",
    "A good idea becomes a business through delivery. Listening to customers, communicating clearly and improving how work gets done are habits I bring into product development.": "A good idea becomes a business through delivery. Listening to customers, communicating clearly and improving how work gets done are habits I bring into product development.",
    "Revenue reflects supplied business history. The review count is the total number of Google reviews, not a claim that every review is five-star.": "Revenue reflects supplied business history. The review count is the total number of Google reviews, not a claim that every review is five-star.",
    "The Google listing is linked directly. No customer quotes have been invented for this portfolio.": "The Google listing is linked directly. No customer quotes have been invented for this portfolio.",
