    "05 / ENGINEERING NOTES": "05 / ENGINEERING NOTES",
    "How I work": "How I work",
    "AI helps me explore and build quickly. Defining the right problem, noticing when the result is wrong and turning it into useful software remain my responsibility.": "AI helps me explore and build quickly. Defining the right problem, noticing when the result is wrong and turning it into useful software remain my responsibility.",
    "Ship": "Ship",
    "Producing more code does not answer whether the product should exist or whether it works for the person using it. My workflow starts with the problem and the customer context.": "Producing more code does not answer whether the product should exist or whether it works for the person using it. My workflow starts with the problem and the customer context.",
    "Research the task, constraints and existing behavior before choosing an implementation.": "Research the task, constraints and existing behavior before choosing an implementation.",
    "Write requirements and direct coding agents with a defined outcome.": "Write requirements and direct coding agents with a defined outcome.",
    "Inspect the implementation, test the experience and deliberately look for failure cases.": "Inspect the implementation, test the experience and deliberately look for failure cases.",
    "Debug, audit and verify changes before shipping; keep known limitations visible.": "Debug, audit and verify changes before shipping; keep known limitations visible.",
    "The UGC Camera and MenuTap story grew from an earlier, broader FoodSpot exploration. The Mac projects also show why fast implementation needs a feedback loop: dictation can lag, file automation needs review and display streaming remains experimental.": "The UGC Camera and MenuTap story grew from an earlier, broader FoodSpot exploration. The Mac projects also show why fast implementation needs a feedback loop: dictation can lag, file automation needs review and display streaming remains experimental.",
    "I want to keep improving this judgment alongside stronger engineers, close to both the product and its customers.": "I want to keep improving this judgment alongside stronger engineers, close to both the product and its customers.",
    "These are authored summaries of my supplied workflow and project notes. They are not a test log or a claim that every project has the same verification history.": "These are authored summaries of my supplied workflow and project notes. They are not a test log or a claim that every project has the same verification history.",
