    "Select a Mac app preview": "Seleccione una vista previa de la aplicación Mac",
    "Problem": "Problema",
    "Start with a real frustration. What would a better experience look like?": "Comienza con una verdadera frustración. ¿Cómo sería una mejor experiencia?",
    "Research": "Investigación",
    "Understand the people, existing tools, and constraints before choosing a solution.": "Comprenda a las personas, las herramientas existentes y las limitaciones antes de elegir una solución.",
    "Think": "Piensa",
    "Make the product decisions. AI can help explore; the judgment stays mine.": "Tomar las decisiones sobre el producto. La IA puede ayudar a explorar; la sentencia sigue siendo mía.",
    "Turn the idea into clear requirements, user flows, and a scope that can ship.": "Convierta la idea en requisitos claros, flujos de usuarios y un alcance que se pueda implementar.",
    "Build with AI": "Construye con IA",
    "Direct coding agents with context and requirements. Review what they produce.": "Agentes de codificación directa con contexto y requisitos. Revisa lo que producen.",
    "Test": "Prueba",
    "Check the actual experience, including on real devices where the product needs them.": "Compruebe la experiencia real, incluso en dispositivos reales donde el producto los necesita.",
    "Break it": "Rómpelo",
    "Try the awkward cases. Slow connections, bad input, and things outside the happy path.": "Pruebe los casos incómodos. Conexiones lentas, malos aportes y cosas fuera del camino feliz.",
    "Audit & fix": "Auditoría y corrección",
    "Inspect the implementation, debug the failures, and verify the changes.": "Inspecciona la implementación, depura las fallas y verifica los cambios.",
    "Ship it": "Envíalo",
    "Put it into people’s hands. Learn from what happens next.": "Ponlo en manos de la gente. Aprenda de lo que sucede a continuación.",
    "Chrome DevTools": "Herramientas de desarrollo de Chrome",
    "Safari Web Inspector": "Inspector web de Safari",
    "Vercel Logs": "Registros de Vercel",
    "Supabase Edge Function Logs": "Registros de funciones de borde de Supabase",
    "UGC Camera": "UGC Camera",
    "Sticker touch targets were too small.": "Los objetivos táctiles de las pegatinas eran demasiado pequeños.",
    "Dragging and deleting worked, but resizing and rotating stickers felt too precise on mobile. I compared the interaction directly with Instagram’s sticker controls and realized our interactive touch area was smaller. The touch target was expanded without unnecessarily making the visible control larger, making the interaction easier to use on a phone.": "Arrastrar y eliminar funcionó, pero cambiar el tamaño y rotar las pegatinas parecía demasiado preciso en el móvil. Comparé la interacción directamente con los controles de pegatinas de Instagram y me di cuenta de que nuestra área táctil interactiva era más pequeña. El objetivo táctil se amplió sin agrandar innecesariamente el control visible, lo que hizo que la interacción fuera más fácil de usar en un teléfono.",
    "${A}desktop/ugc-salad-spot.webp": "${A}escritorio/ugc-salad-spot.webp",
    "Salad Spot branded-camera photo from UGC Camera": "Foto de cámara de marca Salad Spot de UGC Camera",
    "Login looked successful — then something downstream failed.": "El inicio de sesión parecía exitoso; luego, algo falló.",
    "When authentication appeared to complete but the app stalled or returned an error, I started with the callback URL and browser console. If the frontend didn’t explain enough, I traced the problem through Supabase Edge Function logs and database access. In some cases, RLS/data access was blocking the expected operation.": "Cuando la autenticación pareció completarse pero la aplicación se detuvo o devolvió un error, comencé con la URL de devolución de llamada y la consola del navegador. Si la interfaz no explicaba lo suficiente, rastreé el problema a través de los registros de la función Supabase Edge y el acceso a la base de datos. En algunos casos, el acceso a datos o RLS bloqueaba la operación esperada.",
    "URL state": "Estado de la URL",
    "Console": "Consola",
    "Edge Function logs": "Registros de funciones de borde",
    "RLS/data access": "RLS/acceso a datos",
    "Retest": "Volver a probar",
    "iVoz (macOS)": "iVoz (macOS)",
    "Hotkeys and permissions weren’t behaving correctly.": "Las teclas de acceso rápido y los permisos no se comportaban correctamente.",
    "Some keyboard shortcuts weren’t being recognized consistently, and microphone permission could be requested again after relaunching the app. I tested different hotkeys and repeated launch/permission scenarios on macOS until the shortcut handling and permission flow behaved reliably.": "Algunos atajos de teclado no se reconocían de manera consistente y se podía solicitar nuevamente el permiso del micrófono después de reiniciar la aplicación. Probé diferentes teclas de acceso rápido y repetí escenarios de inicio/permisos en macOS hasta que el manejo de accesos directos y el flujo de permisos se comportaron de manera confiable.",
    "${A}desktop/ivoz-window-real.webp": "${A}escritorio/ivoz-window-real.webp",
