    "I’m always open to new opportunities, collaborations and interesting problems to solve. Whether it’s a product, a role, or just an idea — let’s talk.": "Siempre estoy abierto a nuevas oportunidades, colaboraciones y problemas interesantes que resolver. Ya sea un producto, una función o simplemente una idea, hablemos.",
