    "133K / 60 days": "133K / 60 días",
    "HAVE A PRODUCT TO TEST?": "¿TIENES UN PRODUCTO PARA PROBAR?",
    "Let’s find the part": "Busquemos la pieza",
    "people will remember.": "la gente lo recordará.",
    "PRODUCT-FIRST, SHORT-FORM STORYTELLING": "PRODUCTO PRIMERO, NARRACIÓN BREVE",
    "How it comes together": "Cómo se combina",
    "Start with the real product": "Comience con el producto real",
    "I use the app, test its workflows, and look for the useful, surprising, or confusing parts a viewer should actually see.": "Utilizo la aplicación, pruebo sus flujos de trabajo y busco las partes útiles, sorprendentes o confusas que un espectador debería ver.",
    "Make the value easy to get": "Haga que el valor sea fácil de obtener",
    "I shape that experience into a short demo or UGC-style video with a clear opening, real product footage, and a point worth remembering.": "Doy forma a esa experiencia en una demostración breve o en un vídeo estilo UGC con una introducción clara, imágenes reales del producto y un punto que vale la pena recordar.",
    "Speak to your audience": "Habla con tu audiencia",
    "Content can be made in English or Spanish, with the product and its audience guiding the angle and language.": "El contenido puede realizarse en inglés o español, siendo el producto y su audiencia los que guían el ángulo y el lenguaje.",
    "A GOOD FIT FOR": "UN BUEN AJUSTE PARA",
    "Products that are better": "Productos que son mejores",
    "when someone sees them work.": "cuando alguien los ve trabajar.",
    "AI tools, SaaS, mobile apps, and software startups that want product-led demos, first-use reactions, or short-form content grounded in actual product testing.": "Herramientas de inteligencia artificial, SaaS, aplicaciones móviles y nuevas empresas de software que desean demostraciones basadas en productos, reacciones de primer uso o contenido breve basado en pruebas de productos reales.",
    "A FEW PRACTICAL DETAILS": "ALGUNOS DETALLES PRÁCTICOS",
    "Frequently asked questions": "Preguntas frecuentes",
    "Do you make UGC videos for AI startups?": "¿Haces videos UGC para nuevas empresas de IA?",
    "Yes. I make short-form, UGC-style product videos for AI startups by exploring the product and shaping a real use case into a clear story.": "Sí. Hago videos de productos breves, estilo UGC, para nuevas empresas de IA, explorando el producto y dando forma a un caso de uso real en una historia clara.",
    "Do you create product demos for SaaS products?": "¿Crean demostraciones de productos para productos SaaS?",
    "Yes. SaaS product demos can focus on a real workflow, feature, or moment that helps people understand how the product works.": "Sí. Las demostraciones de productos SaaS pueden centrarse en un flujo de trabajo, una característica o un momento real que ayude a las personas a comprender cómo funciona el producto.",
    "Do you test the product before making the video?": "¿Pruebas el producto antes de hacer el vídeo?",
    "Yes. I use the product first, then build the video around a useful, surprising, or confusing part of that experience.": "Sí. Primero uso el producto y luego construyo el video en torno a una parte útil, sorprendente o confusa de esa experiencia.",
    "Can you create content in English and Spanish?": "¿Puedes crear contenido en inglés y español?",
    "Yes. Content can be created in English or Spanish, with the product and intended audience guiding the language and angle.": "Sí. El contenido se puede crear en inglés o español, siendo el producto y el público objetivo los que guían el idioma y el ángulo.",
    "What types of products are a good fit?": "¿Qué tipos de productos son adecuados?",
    "AI tools, SaaS, mobile apps, and other software products are a good fit when a real workflow or product experience can be shown.": "Las herramientas de inteligencia artificial, SaaS, aplicaciones móviles y otros productos de software son una buena opción cuando se puede mostrar un flujo de trabajo real o una experiencia de producto.",
    "Can startups use the videos on their own social channels?": "¿Pueden las startups utilizar los vídeos en sus propios canales sociales?",
    "We can discuss intended placements and terms for each project before work begins. Usage rights are agreed per project.": "Podemos discutir las ubicaciones y los términos previstos para cada proyecto antes de que comience el trabajo. Los derechos de uso se acuerdan por proyecto.",
