    "Select a Mac app preview": "Selecione uma visualização do aplicativo Mac",
    "Problem": "Problema",
    "Start with a real frustration. What would a better experience look like?": "Comece com uma verdadeira frustração. Como seria uma experiência melhor?",
    "Research": "Pesquisa",
    "Understand the people, existing tools, and constraints before choosing a solution.": "Entenda as pessoas, as ferramentas existentes e as restrições antes de escolher uma solução.",
    "Think": "Pense",
    "Make the product decisions. AI can help explore; the judgment stays mine.": "Tome as decisões sobre o produto. A IA pode ajudar a explorar; o julgamento permanece meu.",
    "Turn the idea into clear requirements, user flows, and a scope that can ship.": "Transforme a ideia em requisitos claros, fluxos de usuários e um escopo que possa ser fornecido.",
    "Build with AI": "Construa com IA",
    "Direct coding agents with context and requirements. Review what they produce.": "Agentes de codificação diretos com contexto e requisitos. Revise o que eles produzem.",
    "Test": "Teste",
    "Check the actual experience, including on real devices where the product needs them.": "Verifique a experiência real, inclusive em dispositivos reais onde o produto precisa deles.",
    "Break it": "Quebre isso",
    "Try the awkward cases. Slow connections, bad input, and things outside the happy path.": "Experimente os casos estranhos. Conexões lentas, informações ruins e coisas fora do caminho feliz.",
    "Audit & fix": "Auditoria e correção",
    "Inspect the implementation, debug the failures, and verify the changes.": "Inspecione a implementação, depure as falhas e verifique as alterações.",
    "Ship it": "Envie",
    "Put it into people’s hands. Learn from what happens next.": "Coloque nas mãos das pessoas. Aprenda com o que acontece a seguir.",
    "Chrome DevTools": "Ferramentas de desenvolvimento do Chrome",
