    "UGC Camera": "UGC Camera",
    "Sticker touch targets were too small.": "Os alvos de toque dos adesivos eram muito pequenos.",
    "Dragging and deleting worked, but resizing and rotating stickers felt too precise on mobile. I compared the interaction directly with Instagram’s sticker controls and realized our interactive touch area was smaller. The touch target was expanded without unnecessarily making the visible control larger, making the interaction easier to use on a phone.": "Arrastar e excluir funcionou, mas redimensionar e girar os adesivos parecia muito preciso no celular. Comparei a interação diretamente com os controles de adesivos do Instagram e percebi que nossa área de toque interativa era menor. O alvo de toque foi expandido sem aumentar desnecessariamente o controle visível, tornando a interação mais fácil de usar em um telefone.",
    "${A}desktop/ugc-salad-spot.webp": "${A}desktop/ugc-salad-spot.webp",
    "Salad Spot branded-camera photo from UGC Camera": "Foto da câmera da marca Salad Spot da UGC Camera",
    "Login looked successful — then something downstream failed.": "O login pareceu bem-sucedido - então algo posterior falhou.",
    "When authentication appeared to complete but the app stalled or returned an error, I started with the callback URL and browser console. If the frontend didn’t explain enough, I traced the problem through Supabase Edge Function logs and database access. In some cases, RLS/data access was blocking the expected operation.": "Quando a autenticação parecia estar concluída, mas o aplicativo travou ou retornou um erro, comecei com o URL de retorno de chamada e o console do navegador. Se o frontend não explicasse o suficiente, rastreei o problema por meio dos logs do Supabase Edge Function e do acesso ao banco de dados. Em alguns casos, o acesso RLS/dados estava bloqueando a operação esperada.",
    "URL state": "Estado do URL",
    "Console": "Console",
    "Edge Function logs": "Registros de funções de borda",
    "RLS/data access": "RLS/acesso a dados",
    "Retest": "Teste novamente",
    "iVoz (macOS)": "iVoz (macOS)",
    "Hotkeys and permissions weren’t behaving correctly.": "As teclas de atalho e as permissões não estavam se comportando corretamente.",
    "Some keyboard shortcuts weren’t being recognized consistently, and microphone permission could be requested again after relaunching the app. I tested different hotkeys and repeated launch/permission scenarios on macOS until the shortcut handling and permission flow behaved reliably.": "Alguns atalhos de teclado não eram reconhecidos de forma consistente e a permissão do microfone poderia ser solicitada novamente após reiniciar o aplicativo. Testei diferentes teclas de atalho e repeti cenários de inicialização/permissão no macOS até que o tratamento de atalhos e o fluxo de permissão se comportassem de maneira confiável.",
